1	//! Typed calls over one session of the linked checker ([`crate::checker`]). Wire shapes are the ones the official 7.1
2	//! client sends (traced against `7.1.0-beta`); a method this module does not name is not used.
3	
4	use std::collections::BTreeMap;
5	use std::sync::{Arc, Mutex};
6	use std::time::Duration;
