15	/// Why a call failed, split by whether the rest of the run can go on.
16	#[derive(Debug)]
17	pub(crate) enum CallError {
18	    /// The session is gone or stuck: every later call would fail the same way.
19	    Fatal(String),
20	    /// The checker rejected this one call; other components may still resolve.
21	    Rejected(String),
22	}
23	
24	impl std::fmt::Display for CallError {
25	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
26	        match self {
27	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
28	        }
29	    }
30	}
31	
32	fn classify(error: RequestError) -> CallError {
33	    match error {
34	        RequestError::Rejected(message) => CallError::Rejected(message),
35	        other => CallError::Fatal(other.to_string()),
36	    }
37	}
