65	/// A symbol as another response embeds it: the id, and the node id of the file that owns it. The full symbol is one
66	/// call away (`getSymbolOfType`, `getAliasSymbolOfType`).
67	#[derive(Debug, Clone, PartialEq, Eq, Hash, Deserialize)]
68	pub(crate) struct CompactSymbol {
69	    pub id: u64,
70	    #[serde(default)]
71	    pub file: Option<String>,
72	}
73	
74	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
75	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
76	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
77	/// so are the internal names, which start with exactly two.
78	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
79	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
80	}
81	
82	fn unescaped_name<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
83	    let name = String::deserialize(deserializer)?;
84	    Ok(unescape_leading_underscores(&name).to_string())
85	}
