89	pub(crate) struct TypeInfo {
90	    pub id: u64,
91	    pub flags: u64,
92	    #[serde(default)]
93	    pub object_flags: u64,
94	    #[serde(default)]
95	    pub value: Option<Value>,
96	    #[serde(default)]
97	    pub is_tuple_type: bool,
98	    /// The checker's name for an intrinsic type (`"any"`, `"string"`, `"error"`). It alone tells a written `any` from
99	    /// the error type of an unresolved name: both carry the `Any` flag, and the error type has an id per site.
100	    #[serde(default)]
101	    pub intrinsic_name: Option<String>,
102	    /// `TupleElementFlags` of a tuple type's elements: required 1, optional 2, rest 4, variadic 8.
103	    #[serde(default)]
104	    pub element_flags: Vec<u64>,
105	    /// A tuple type written `readonly [...]`.
106	    #[serde(default)]
107	    pub readonly: bool,
108	    /// One declaration handle per element of a tuple whose elements are labeled, `[head: string]`; empty otherwise.
109	    #[serde(default)]
110	    pub labeled_element_declarations: Vec<String>,
111	    /// The text pieces of a template literal type, around its holes.
112	    #[serde(default)]
113	    pub texts: Vec<String>,
114	    /// The `this` type of a class or interface, which the checker also appends to a reference's type arguments.
115	    #[serde(default)]
116	    pub is_this_type: bool,
117	    /// The symbol that declares an object type; absent for primitives and unions.
118	    #[serde(default)]
119	    pub symbol: Option<CompactSymbol>,
120	    /// The alias this type was written through, `Size` in `type Size = "sm" | "lg"`.
121	    #[serde(default)]
122	    pub alias_symbol: Option<CompactSymbol>,
123	    /// Ids of the alias's type arguments; `Rpc::alias_type_arguments` fetches them.
124	    #[serde(default)]
125	    pub alias_type_arguments: Vec<u64>,
126	    /// The keys a mapped type ranges over (`keyof Conditions` in `{ [K in keyof Conditions]?: V }`), as the checker's
127	    /// type handle; absent for a type that is not a mapped type.
128	    #[serde(default)]
129	    pub constraint_type: Option<u64>,
130	    /// The `as` clause of a mapped type, which renames its keys; absent when it has none.
131	    #[serde(default)]
132	    pub name_type: Option<u64>,
133	}
