135	impl TypeInfo {
136	    /// The checker's error type: what a name that does not resolve is typed as.
137	    pub(crate) fn is_error(&self) -> bool {
138	        self.flags & flag::ANY != 0 && self.intrinsic_name.as_deref() == Some("error")
139	    }
