265	/// One checker session bound to a snapshot and project.
266	pub(crate) struct Rpc {
267	    client: Client,
268	    deadline: Duration,
269	    snapshot: u64,
270	    project: String,
271	    /// The compiler options the program was built with, for a snapshot that adds files to it ([`Rpc::layered`]).
272	    options: Value,
273	    /// Every call and its answer, when the caller asked to record a replay fixture; shared with a layered snapshot.
274	    recording: Option<Arc<Mutex<Vec<Value>>>>,
275	    calls: Arc<Mutex<BTreeMap<String, u64>>>,
276	}
