278	/// A diagnostic the checker reports for a file: where it starts and what it says.
279	#[derive(Debug, Clone, Deserialize)]
280	#[serde(rename_all = "camelCase")]
281	pub(crate) struct FileDiagnostic {
282	    /// The file the error is in, which is not always the file asked about.
283	    pub file_name: String,
284	    pub start_position: Position,
285	    /// `DiagnosticCategory`: warning 0, error 1, suggestion 2, message 3.
286	    pub category: u8,
287	    /// The message; a chain of messages arrives as an object, of which only the first is shown.
288	    pub text: Value,
289	}
290	
291	impl FileDiagnostic {
292	    pub(crate) fn is_error(&self) -> bool {
293	        self.category == 1
294	    }
295	
296	    pub(crate) fn message(&self) -> String {
297	        match &self.text {
298	            Value::String(text) => text.clone(),
299	            other => other.get("messageText").and_then(Value::as_str).unwrap_or("a type error").to_string(),
300	        }
301	    }
302	}
