310	impl Rpc {
311	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
312	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
313	    /// numeric ones.
314	    pub(crate) async fn prepare(
315	        client: &Client,
316	        deadline: Duration,
317	        tsconfig: Option<&str>,
318	    ) -> Result<Value, CallError> {
319	        let rpc = Rpc {
320	            client: client.clone(),
321	            deadline,
322	            snapshot: 0,
323	            project: String::new(),
324	            options: Value::Null,
325	            recording: None,
326	            calls: Arc::default(),
327	        };
328	        rpc.call("initialize", Value::Null).await?;
329	        Ok(match tsconfig {
330	            Some(file) => {
331	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
332	                parsed.get("options").cloned().unwrap_or_else(default_options)
333	            }
334	            None => default_options(),
335	        })
336	    }
337	
338	    /// A snapshot of `count` programs over the same `root_files` (one when `count` is at most one), in a session it
339	    /// initializes first ([`Rpc::prepare`]), with one session bound to each program: a checker that answers requests
340	    /// about different programs at once ([`crate::checker::InProcess`]) answers the sessions in parallel. The programs
341	    /// read the same files, so each answers what any other would. They share the request counts and the recording;
342	    /// [`Rpc::release`] on the first releases the snapshot, and with it every program.
343	    pub(crate) async fn open_programs(
344	        client: Client,
345	        deadline: Duration,
346	        tsconfig: Option<&str>,
347	        root_files: &[String],
348	        record: bool,
349	        count: usize,
350	    ) -> Result<Vec<Rpc>, CallError> {
351	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
352	        if count <= 1 {
353	            return Ok(vec![Rpc::open_with(client, deadline, &options, root_files, record).await?]);
354	        }
355	        let first = Rpc {
356	            client,
357	            deadline,
358	            snapshot: 0,
359	            project: String::new(),
360	            options: options.clone(),
361	            recording: record.then(Arc::default),
362	            calls: Arc::default(),
363	        };
364	        let program = json!({ "rootFiles": root_files, "compilerOptions": options });
365	        let programs: Vec<Value> = std::iter::repeat_n(program, count).collect();
366	        let response: SnapshotResponse =
367	            decode(&first.call("createSnapshot", json!({ "createPrograms": programs })).await?)?;
368	        if response.projects.len() != count {
369	            // Nothing will hold this snapshot to release it later.
370	            Rpc { snapshot: response.snapshot, ..first }.release().await;
371	            return Err(CallError::Rejected(format!(
372	                "createSnapshot made {} programs of {count}",
373	                response.projects.len()
374	            )));
375	        }
376	        Ok(response
377	            .projects
378	            .into_iter()
379	            .enumerate()
380	            .map(|(lane, project)| Rpc {
381	                client: first.client.lane(lane),
382	                deadline,
383	                snapshot: response.snapshot,
384	                project: project.id,
385	                options: options.clone(),
386	                recording: first.recording.clone(),
387	                calls: first.calls.clone(),
388	            })
389	            .collect())
390	    }
391	
392	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
393	    pub(crate) async fn open_with(
394	        client: Client,
395	        deadline: Duration,
396	        options: &Value,
397	        root_files: &[String],
398	        record: bool,
399	    ) -> Result<Rpc, CallError> {
400	        let rpc = Rpc {
401	            client,
402	            deadline,
403	            snapshot: 0,
404	            project: String::new(),
405	            options: options.clone(),
406	            recording: record.then(Arc::default),
407	            calls: Arc::default(),
408	        };
409	        rpc.created(json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] })).await
410	    }
411	
412	    /// A new snapshot of the same program with `files` added, held in the checker's memory and never written to disk:
413	    /// each is a root file, keyed by its absolute path. The calls on it count, and are recorded, with this one's.
414	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
415	        let rpc = Rpc {
416	            client: self.client.clone(),
417	            deadline: self.deadline,
418	            snapshot: 0,
419	            project: String::new(),
420	            options: self.options.clone(),
421	            recording: self.recording.clone(),
422	            calls: self.calls.clone(),
423	        };
424	        let mut roots = root_files.to_vec();
425	        roots.extend(files.iter().map(|(path, _)| path.clone()));
426	        let layer: serde_json::Map<String, Value> =
427	            files.iter().map(|(path, text)| (path.clone(), Value::String(text.clone()))).collect();
428	        rpc.created(json!({
429	            "fileSystem": { "kind": "layer", "files": layer },
430	            "createPrograms": [{ "rootFiles": roots, "compilerOptions": self.options }],
431	        }))
432	        .await
433	    }
434	
435	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
436	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
437	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
438	    /// only when it is rebuilt. This snapshot stays alive until it is released.
439	    pub(crate) async fn updated(
440	        &self,
441	        changed: &[String],
442	        deleted: &[String],
443	        roots: Option<&[String]>,
444	    ) -> Result<Rpc, CallError> {
445	        let mut changes = serde_json::Map::new();
446	        if !changed.is_empty() || !deleted.is_empty() {
447	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
448	        }
449	        if let Some(roots) = roots {
450	            changes.insert(
451	                "reconfigurePrograms".to_string(),
452	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
453	            );
454	        }
455	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
456	        let response: SnapshotResponse =
457	            decode(&self.call("updateSnapshot", json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
458	        // The response lists only the projects it replaced; the synthetic program keeps its id.
459	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
460	        Ok(Rpc {
461	            client: self.client.clone(),
462	            deadline: self.deadline,
463	            snapshot: response.snapshot,
464	            project,
465	            options: self.options.clone(),
466	            recording: self.recording.clone(),
467	            calls: Arc::default(),
468	        })
469	    }
470	
471	    /// Every file the snapshot's program read, as the checker names them.
472	    pub(crate) async fn source_file_names(&self) -> Result<Vec<String>, CallError> {
473	        self.scoped("getSourceFileNames", json!({})).await
474	    }
475	
476	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
477	    async fn created(mut self, params: Value) -> Result<Rpc, CallError> {
478	        let response: SnapshotResponse = decode(&self.call("createSnapshot", params).await?)?;
479	        self.snapshot = response.snapshot;
480	        let Some(project) = response.projects.into_iter().next() else {
481	            // Nothing will hold this snapshot to release it later.
482	            self.release().await;
483	            return Err(CallError::Rejected("createSnapshot returned no project".to_string()));
484	        };
485	        self.project = project.id;
486	        Ok(self)
487	    }
488	
489	    pub(crate) async fn release(&self) {
490	        self.call("release", json!({ "snapshot": self.snapshot })).await.ok();
491	    }
492	
493	    /// The recorded calls as a JSON array, or `None` when recording was off.
494	    pub(crate) fn recording(&self) -> Option<Value> {
495	        let log = self.recording.as_ref()?.lock().ok()?;
496	        Some(Value::Array(log.clone()))
497	    }
498	
499	    /// Requests sent so far, by method.
500	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
501	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
502	    }
503	
504	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
505	    /// expects.
506	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
507	        if let Ok(mut calls) = self.calls.lock() {
508	            *calls.entry(method.to_string()).or_default() += 1;
509	        }
510	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
511	        let Some(log) = &self.recording else {
512	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
513	        };
514	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
515	        let result: Value = decode(&answer)?;
516	        if let Ok(mut log) = log.lock() {
517	            log.push(json!({ "method": method, "params": params, "result": result }));
518	        }
519	        Ok(answer)
520	    }
521	
522	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
523	        decode(&self.scoped_text(method, extra).await?)
524	    }
