526	    /// A request about this snapshot and project, its answer left as text.
527	    async fn scoped_text(&self, method: &str, extra: Value) -> Result<Box<RawValue>, CallError> {
528	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
529	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
530	            base.extend(extra);
531	        }
