602	        self.scoped("getParentOfSymbolForChecker", json!({ "symbol": symbol })).await
603	    }
604	
605	    /// Whether each property is declared `readonly`, in one round trip.
606	    pub(crate) async fn readonly_symbols(&self, symbols: &[&Value]) -> Result<Vec<bool>, CallError> {
607	        let requests = symbols.iter().map(|symbol| ("isReadonlySymbol", json!({ "symbol": symbol }))).collect();
608	        self.batch(requests).await?.iter().map(|answer| decode(answer)).collect()
609	    }
610	
611	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
612	    /// that may legitimately fail.
613	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
614	        let wanted = requests.len();
615	        let scoped: Vec<Value> = requests
616	            .into_iter()
617	            .map(|(method, mut params)| {
618	                if let Value::Object(map) = &mut params {
619	                    map.insert("snapshot".to_string(), json!(self.snapshot));
620	                    map.insert("project".to_string(), json!(self.project));
621	                }
622	                json!({ "method": method, "params": params })
623	            })
624	            .collect();
625	        let mut answers = Vec::with_capacity(wanted);
626	        let mut token: Option<String> = None;
627	        loop {
628	            let mut params = json!({ "requests": scoped });
629	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
630	                map.insert("continuationToken".to_string(), json!(token));
631	            }
632	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
633	            for response in page.responses {
634	                if let Some(error) = response.error {
635	                    return Err(CallError::Rejected(error));
636	                }
637	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
638	            }
639	            match page.continuation_token {
640	                Some(next) => token = Some(next),
641	                None => break,
642	            }
643	        }
644	        if answers.len() != wanted {
645	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
646	        }
647	        Ok(answers)
648	    }
649	
650	    pub(crate) async fn parameters(&self, signature: u64) -> Result<Vec<SymbolInfo>, CallError> {
651	        self.scoped("getParametersOfSignature", json!({ "objectId": signature })).await
652	    }
653	
654	    pub(crate) async fn return_type(&self, signature: u64) -> Result<TypeInfo, CallError> {
655	        self.scoped("getReturnTypeOfSignature", json!({ "objectId": signature })).await
656	    }
657	
658	    pub(crate) async fn properties(&self, type_id: u64) -> Result<Vec<SymbolInfo>, CallError> {
659	        self.scoped("getPropertiesOfType", json!({ "type": type_id })).await
660	    }
661	
662	    /// The members of a union, intersection or template literal, as the text the checker answered (a list of types).
663	    pub(crate) async fn members_text(&self, type_id: u64) -> Result<Box<RawValue>, CallError> {
664	        self.scoped_text("getTypesOfType", json!({ "objectId": type_id })).await
665	    }
666	
667	    /// The type arguments of a reference, as the text the checker answered (a list of types).
668	    pub(crate) async fn type_arguments_text(&self, type_id: u64) -> Result<Box<RawValue>, CallError> {
669	        self.scoped_text("getTypeArguments", json!({ "type": type_id })).await
670	    }
671	
672	    /// The call and construct signatures, the properties and the index signatures of a type, in one round trip.
673	    pub(crate) async fn object_members(&self, type_id: u64) -> Result<ObjectMembers, CallError> {
674	        let requests = vec![
675	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Call as u8 })),
676	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Construct as u8 })),
677	            ("getPropertiesOfType", json!({ "type": type_id })),
678	            ("getIndexInfosOfType", json!({ "type": type_id })),
679	        ];
680	        let mut answers = self.batch(requests).await?.into_iter();
681	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
682	        Ok(ObjectMembers {
683	            calls: decode(&next()?)?,
684	            constructs: decode(&next()?)?,
685	            properties: decode(&next()?)?,
686	            indexes: decode(&next()?)?,
687	        })
688	    }
689	
690	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
691	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
692	    }
693	
694	    pub(crate) async fn type_to_string(&self, type_id: u64) -> Result<String, CallError> {
695	        self.scoped("typeToString", json!({ "type": type_id })).await
696	    }
697	
698	    /// The type as written inside a type alias declaration, and never cut short: an alias at the top is printed as what
699	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
700	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
701	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
702	    }
703	}
704	
705	fn default_options() -> Value {
706	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
707	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
708	}
709	
710	/// An answer parsed from its text straight into `T`, in one pass.
711	pub(crate) fn decode<T: DeserializeOwned>(answer: &RawValue) -> Result<T, CallError> {
712	    serde_json::from_str(answer.get())
713	        .map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
714	}
715	
716	#[cfg(test)]
717	mod tests {
718	    use super::*;
719	
720	    #[test]
721	    fn a_name_with_three_or_more_leading_underscores_loses_the_one_the_checker_added() {
722	        assert_eq!(unescape_leading_underscores("___size"), "__size");
723	        assert_eq!(unescape_leading_underscores("____triple"), "___triple");
724	        assert_eq!(unescape_leading_underscores("___0"), "__0");
725	    }
