1	//! The checker a run asks: the `tsrs` crates linked into this process, asked through `tsrs_api::Session` with the
2	//! methods and JSON of `tsc --api` ([`crate::rpc`]).
3	//!
4	//! The linked checker answers on threads of its own with a 512 MiB stack, the stack the `tsrs` binary serves on. A
5	//! query runs on the thread that calls it, and a type nested 2,000 deep overflows a default 2 MiB thread: a stack
6	//! overflow aborts the whole process and cannot be caught. Callers on any thread send it requests over a channel, one
7	//! per checker thread (a lane), and each thread answers its own one at a time, in the order they arrive; a run that asks
8	//! several programs at once sends each program's requests down a lane of its own ([`Client::lane`]). Every lane asks
9	//! the same session.
10	//!
11	//! It is guarded so that it does not take its host (Node, Storybook) down with it:
12	//!
13	//! - **Panics.** A panic inside the checker comes back as an error to the request that caused it, and every lane then
14	//!   stops: a request any lane takes afterwards fails, and the last lane to leave closes the session, as a crashed
15	//!   process would end. A session a panic unwound through is not asked again, so no later answer comes from state it
16	//!   left half-built. The caller starts a fresh one ([`crate::on_demand`] does, up to its restart limit; a
17	//!   whole-project run fails on the first lane's error and answers structurally). A panic `tsrs` itself reports as the
18	//!   client's fault (an unknown `moduleResolution`) is an error like any other, and the session keeps answering.
19	//! - **Nesting.** `tsrs` parses on threads of its own with a 256 MiB stack, which a file nested a few hundred thousand
20	//!   brackets deep overflows (measured on macOS arm64: an object type 200,000 deep parses, 300,000 aborts). Every file
21	//!   the checker reads from the disk is measured first ([`nesting`]), and a request that read one nested deeper than
22	//!   [`MAX_NESTING`] fails with an error that names it, so its components keep their structural answer. Requests that
23	//!   build snapshots, which are the ones that read files, run one at a time across the lanes, so a refusal is the
24	//!   request's that met it; any other request that sees a refusal fails too.
25	//! - **Memory.** [`Backend::memory_mib`] reads what the linked checker holds: the resident part of the address range
26	//!   `tsrs` allocates its arenas from, which leaves out the host's own memory. [`crate::on_demand`] bounds it.
27	
28	use std::panic::{AssertUnwindSafe, catch_unwind};
29	use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
30	use std::sync::{Arc, Mutex, RwLock, mpsc};
31	use std::thread::JoinHandle;
32	use std::time::Duration;
33	
34	use camino::Utf8Path;
35	use serde_json::Value;
36	use serde_json::value::RawValue;
37	use tokio::sync::oneshot;
38	use tsrs_api::{ErrorKind, Handler, Response, Session, SessionOptions};
39	use tsrs_vfs::{FS, bundled, osvfs, wrapvfs};
40	
41	/// The stack of the thread the linked checker answers on: what the `tsrs` binary gives each of its threads.
42	const CHECKER_STACK_BYTES: usize = 512 << 20;
43	
44	/// The deepest bracket nesting a file may have for the linked checker to read it: twice the 10,000 levels the deep-type
45	/// tests print in full, and a tenth of the 200,000 an object type was measured to parse at on `tsrs`'s 256 MiB parse
46	/// threads (300,000 overflows them, which aborts the process).
47	pub(crate) const MAX_NESTING: usize = 20_000;
48	
49	/// Why the checker did not answer a request.
50	#[derive(Debug)]
51	pub(crate) enum RequestError {
52	    /// The checker answered with an error (a panic inside it among them): this request failed.
53	    Rejected(String),
54	    /// No answer came within the deadline.
55	    Timeout { method: String, after: Duration },
56	    /// The checker was stopped, or its session could not be created.
57	    Closed,
58	    /// The request could not be written as JSON, or the answer is not JSON.
59	    Malformed(String),
60	}
61	
62	impl std::fmt::Display for RequestError {
63	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
64	        match self {
65	            RequestError::Rejected(message) | RequestError::Malformed(message) => f.write_str(message),
66	            RequestError::Timeout { method, after } => write!(f, "request {method:?} timed out after {after:?}"),
67	            RequestError::Closed => f.write_str("session shut down"),
68	        }
69	    }
70	}
71	
72	/// The linked checker: the first of the threads that share its session, and the way to them.
73	pub(crate) struct Backend {
74	    client: Client,
75	    thread: JoinHandle<()>,
76	    threads: usize,
77	    /// Set by a thread, before it answers, when no thread will answer anything more: a panic unwound through the
78	    /// session.
79	    ended: Arc<AtomicBool>,
80	    /// Disconnected once every thread has left and the last has closed the session.
81	    closed: mpsc::Receiver<()>,
82	}
83	
84	impl Backend {
85	    /// Spawns the checker thread, which creates its session there: the session's work, from the first request on,
86	    /// runs on that thread's stack. With `threads` above one it starts as many more, each answering a queue of its own
87	    /// (a lane, [`Client::lane`]) on the same session: requests about one program wait for each other (each program
88	    /// has one checker, which `tsrs_api` locks for the length of a request), so a run that sends the requests about
89	    /// each of its programs down a lane of its own has them answered at once. A thread that cannot be spawned is an
90	    /// error that says so.
91	    pub(crate) fn start(project_root: &Utf8Path, threads: usize) -> Result<Backend, String> {
92	        let cwd = project_root.to_string();
93	        Backend::spawn(threads, move || TsrsSession::open(cwd))
94	    }
95	
96	    /// Spawns the checker threads over the session `open` makes on the first.
97	    pub(crate) fn spawn<S: Served + Send + Sync + 'static>(
98	        threads: usize,
99	        open: impl FnOnce() -> S + Send + 'static,
100	    ) -> Result<Backend, String> {
101	        let (lanes, queues): (Vec<_>, Vec<_>) = (0..threads.max(1)).map(|_| mpsc::channel()).unzip();
102	        let threads = lanes.len();
103	        let ended = Arc::new(AtomicBool::new(false));
104	        let thread_ended = Arc::clone(&ended);
105	        let (closing, closed) = mpsc::channel::<()>();
106	        let thread = std::thread::Builder::new()
107	            .name("caliper-checker".to_string())
108	            .stack_size(CHECKER_STACK_BYTES)
109	            .spawn(move || serve(open, queues, thread_ended, closing))
110	            .map_err(|error| format!("could not start the checker thread: {error}"))?;
111	        Ok(Backend { client: Client { lanes: lanes.into(), lane: 0 }, thread, threads, ended, closed })
112	    }
