166	/// The deepest bracket nesting of `text`: `(`, `[` and `{` counted together and `<` apart, each closer taking a level
167	/// off (never below zero). A nested type or expression written with brackets is a level of the parser's recursion, so
168	/// this bounds how deep a file makes it recurse. Brackets in strings and comments count too, which can only raise the
169	/// number. Angles are counted apart because the `>` of every `=>` closes one.
170	pub(crate) fn nesting(text: &str) -> usize {
171	    let (mut brackets, mut angles, mut deepest) = (0usize, 0usize, 0usize);
172	    for byte in text.bytes() {
173	        match byte {
174	            b'(' | b'[' | b'{' => {
175	                brackets += 1;
176	                deepest = deepest.max(brackets);
177	            }
178	            b')' | b']' | b'}' => brackets = brackets.saturating_sub(1),
179	            b'<' => {
180	                angles += 1;
181	                deepest = deepest.max(angles);
182	            }
183	            b'>' => angles = angles.saturating_sub(1),
184	            _ => {}
185	        }
186	    }
187	    deepest
188	}
