216	    /// One request, its answer the `result` as the JSON text it arrived as. The wait is bounded by `deadline`.
217	    pub(crate) async fn request_raw(
218	        &self,
219	        method: &str,
220	        params: Value,
221	        deadline: Duration,
222	    ) -> Result<Box<RawValue>, RequestError> {
223	        let params = serde_json::to_vec(&params)
224	            .map_err(|error| RequestError::Malformed(format!("failed to serialize a request: {error}")))?;
225	        let (reply, answer) = oneshot::channel();
226	        let asked = Asked { method: method.to_string(), params, reply };
227	        let Some(jobs) = self.lanes.get(self.lane % self.lanes.len().max(1)) else {
228	            return Err(RequestError::Closed);
229	        };
230	        if jobs.send(Job::Request(asked)).is_err() {
231	            return Err(RequestError::Closed);
232	        }
233	        let answered = match tokio::time::timeout(deadline, answer).await {
234	            Ok(Ok(answered)) => answered,
235	            // The thread ended without answering: stopped, or its session could not be created.
236	            Ok(Err(_dropped)) => return Err(RequestError::Closed),
237	            Err(_elapsed) => return Err(RequestError::Timeout { method: method.to_string(), after: deadline }),
238	        };
239	        match answered {
240	            Ok(text) => RawValue::from_string(text)
241	                .map_err(|_invalid| RequestError::Malformed(format!("{method} answered with text that is not JSON"))),
242	            Err(message) => Err(RequestError::Rejected(message)),
243	        }
244	    }
245	
246	    fn stop(&self) {
247	        // A thread that already ended has nothing to stop.
248	        for jobs in self.lanes.iter() {
249	            jobs.send(Job::Stop).ok();
250	        }
251	    }
252	}
