280	/// A `tsrs` session over the disk, where every file is measured before the session reads it.
281	struct TsrsSession {
282	    session: Arc<Session>,
283	    /// The files nested past [`MAX_NESTING`] the session was refused, with their depth (see [`TsrsSession::answer`]).
284	    refused: Arc<Mutex<Vec<(String, usize)>>>,
285	    /// Held alone by a request that builds a snapshot, and shared by every other, across the lanes.
286	    building: RwLock<()>,
287	}
288	
289	impl TsrsSession {
290	    fn open(cwd: String) -> TsrsSession {
291	        let refused: Arc<Mutex<Vec<(String, usize)>>> = Arc::default();
292	        let noted = Arc::clone(&refused);
293	        let measured = wrapvfs::wrap(
294	            osvfs::fs(),
295	            wrapvfs::Replacements {
296	                read_file: Some(Box::new(move |path: &str| {
297	                    let text = osvfs::fs().read_file(path)?;
298	                    let depth = nesting(&text);
299	                    if depth <= MAX_NESTING {
300	                        return Some(text);
301	                    }
302	                    noted.lock().unwrap_or_else(std::sync::PoisonError::into_inner).push((path.to_string(), depth));
303	                    None
304	                })),
305	                ..wrapvfs::Replacements::default()
306	            },
307	        );
308	        let fs: Arc<dyn FS> = Arc::new(bundled::wrap_fs(measured));
309	        let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
310	        TsrsSession { session, refused, building: RwLock::new(()) }
311	    }
312	
313	    fn refused(&self) -> std::sync::MutexGuard<'_, Vec<(String, usize)>> {
314	        self.refused.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
315	    }
316	
317	    /// Answers one request and the refusals it met. A request that builds a snapshot (the ones that read files) has
318	    /// the session to itself among the lanes, so a refusal noted meanwhile is its own; it clears the list before and
319	    /// takes it after. Any other request runs beside the others and only looks: a refusal one of them met (a file read
320	    /// late) fails every request that sees it, until the next snapshot is built.
321	    fn answer(&self, method: &str, params: &[u8]) -> (tsrs_api::ApiResult<Response>, Option<(String, usize)>) {
322	        if matches!(method, "createSnapshot" | "updateSnapshot") {
323	            let _alone = self.building.write().unwrap_or_else(std::sync::PoisonError::into_inner);
324	            self.refused().clear();
325	            let answered = self.session.handle_request(method, params);
326	            let refused = std::mem::take(&mut *self.refused()).into_iter().next();
327	            (answered, refused)
328	        } else {
329	            let _beside = self.building.read().unwrap_or_else(std::sync::PoisonError::into_inner);
330	            let answered = self.session.handle_request(method, params);
331	            let refused = self.refused().first().cloned();
332	            (answered, refused)
333	        }
334	    }
335	}
