337	impl Served for TsrsSession {
338	    fn handle(&self, method: &str, params: &[u8]) -> Result<String, Failure> {
339	        let (answered, refused) = self.answer(method, params);
340	        if let Some((file, depth)) = refused {
341	            // The session answered without the file, which it took for missing: not an answer to give, and a snapshot
342	            // it made for it would be held with no one to release it.
343	            if let Ok(Response::Json(text)) = &answered {
344	                self.discard(method, text);
345	            }
346	            let message = format!(
347	                "{file} nests brackets {depth} deep, more than the {MAX_NESTING} the built-in checker reads without \
348	                 risking a stack overflow; its components keep their structural answer"
349	            );
350	            return Err(Failure { message, panicked: false });
351	        }
352	        match answered {
353	            Ok(Response::Json(text)) => Ok(text),
354	            Ok(Response::Binary(_)) => {
355	                Err(Failure { message: format!("{method} answered in binary, not JSON"), panicked: false })
356	            }
357	            Err(error) => {
358	                let message = error.to_string();
359	                // `tsrs_api` catches a panic in a handler and reports it as an internal error that says so.
360	                let panicked = error.kind == ErrorKind::Internal && message.starts_with("panic: ");
361	                Err(Failure { message, panicked })
362	            }
363	        }
364	    }
365	
366	    fn discard(&self, method: &str, answer: &str) {
367	        if let Some(snapshot) = snapshot_made(method, answer) {
368	            let params = serde_json::json!({ "snapshot": snapshot }).to_string();
369	            if let Err(error) = self.session.handle_request("release", params.as_bytes()) {
370	                tracing::debug!(snapshot, %error, "could not release the snapshot of an answer nobody receives");
371	            }
372	        }
373	    }
374	
375	    fn close(&self) {
376	        self.session.close();
377	    }
378	}
