380	/// The checker threads: one session, each thread answering the requests of its queue (its lane) in turn. The first
381	/// thread creates the session and starts the others.
382	fn serve<S: Served + Send + Sync + 'static>(
383	    open: impl FnOnce() -> S,
384	    queues: Vec<mpsc::Receiver<Job>>,
385	    ended: Arc<AtomicBool>,
386	    closing: mpsc::Sender<()>,
387	) {
388	    let session = Arc::new(open());
389	    let left = Arc::new(AtomicUsize::new(queues.len()));
390	    let mut queues = queues.into_iter();
391	    let Some(own) = queues.next() else {
392	        catch_unwind(AssertUnwindSafe(|| session.close())).ok();
393	        return;
394	    };
395	    for (index, queue) in queues.enumerate() {
396	        let lane =
397	            Lane { session: session.clone(), ended: ended.clone(), left: left.clone(), _closing: closing.clone() };
398	        let spawned = std::thread::Builder::new()
399	            .name(format!("caliper-checker-{}", index + 1))
400	            .stack_size(CHECKER_STACK_BYTES)
401	            .spawn(move || lane.answer(&queue));
402	        // Its queue is dropped with the closure, so its lane's requests fail as from a stopped checker.
403	        if spawned.is_err() {
404	            left.fetch_sub(1, Ordering::AcqRel);
405	        }
406	    }
407	    Lane { session, ended, left, _closing: closing }.answer(&own);
408	}
409	
410	/// What one checker thread shares with the others.
411	struct Lane<S> {
412	    session: Arc<S>,
413	    /// Set, before its reply, by the thread whose request a panic unwound through: no thread answers after it.
414	    ended: Arc<AtomicBool>,
415	    /// The threads that have not left; the last to leave closes the session.
416	    left: Arc<AtomicUsize>,
417	    /// Dropped as the thread leaves: [`Backend::closed`] disconnects once every thread has.
418	    _closing: mpsc::Sender<()>,
419	}
420	
421	impl<S: Served> Lane<S> {
422	    /// The requests of `queue` in turn, until the thread is stopped, every sender is gone, or a panic unwound through
423	    /// the session on any thread. A panic is caught here too, should one escape `tsrs`'s own catch.
424	    fn answer(self, queue: &mpsc::Receiver<Job>) {
425	        for job in queue {
426	            let asked = match job {
427	                Job::Request(asked) => asked,
428	                Job::Stop => break,
429	            };
430	            if self.ended.load(Ordering::Acquire) {
431	                let message = "the built-in checker stopped: a panic unwound through its session".to_string();
432	                asked.reply.send(Err(message)).ok();
433	                break;
434	            }
435	            // A caller that stopped waiting (its deadline passed, its run ended) is not answered.
436	            if asked.reply.is_closed() {
437	                continue;
438	            }
439	            let session = &self.session;
440	            let answered = catch_unwind(AssertUnwindSafe(|| session.handle(&asked.method, &asked.params)))
441	                .unwrap_or_else(|panic| {
442	                    let text = panic
443	                        .downcast_ref::<String>()
444	                        .map(String::as_str)
445	                        .or_else(|| panic.downcast_ref::<&str>().copied())
446	                        .unwrap_or("a panic with no message");
447	                    Err(Failure { message: format!("panic: {text}"), panicked: true })
448	                });
449	            match answered {
450	                Ok(text) => {
451	                    // A caller that stopped waiting meanwhile (its deadline passed) never learns of a snapshot this
452	                    // made.
453	                    if let Err(Ok(unread)) = asked.reply.send(Ok(text)) {
454	                        session.discard(&asked.method, &unread);
455	                    }
456	                }
457	                Err(Failure { message, panicked }) => {
458	                    if panicked {
459	                        tracing::warn!(method = asked.method, %message, "the built-in checker panicked; it is replaced");
460	                        // Before the reply, so the caller never sends its next request to a session that will not
461	                        // answer, and before any other lane takes its next.
462	                        self.ended.store(true, Ordering::Release);
463	                        asked.reply.send(Err(message)).ok();
464	                        break;
465	                    }
466	                    asked.reply.send(Err(message)).ok();
467	                }
468	            }
469	        }
470	        if self.left.fetch_sub(1, Ordering::AcqRel) == 1 {
471	            // A session a panic left half-built may panic again while it closes; the thread ends either way.
472	            catch_unwind(AssertUnwindSafe(|| self.session.close())).ok();
473	        }
474	    }
475	}
