1	//! A warm checker that answers for the components a session asks about, one request at a time.
2	//!
3	//! The one-shot [`crate::resolve`] roots a single program at every component's file. A Storybook session asks about
4	//! one component per story, so this keeps one checker warm, starts it on the first request, and roots a small program at
5	//! just the requested files: the checker loads what those files import, not the project.
6	//!
7	//! The snapshot of that program is kept between requests (ADR 0026 S6). The next request brings it up to date with
8	//! `updateSnapshot`, which re-reads only the files the session announced as changed ([`SemanticProvider::changed`]) and
9	//! keeps the rest as parsed, re-rooting the program when the request names other files. The checker does not see an
10	//! edit it is not told about, so before an answer every file the program read is compared with the stamp it had when
11	//! read ([`crate::stamps`]): one that changed unannounced makes the answer come from a fresh snapshot, with a warning
12	//! that names it.
13	//!
14	//! The worker runs on its own thread with its own runtime, so a caller on any thread (a NAPI worker, a rayon task)
15	//! never nests runtimes and can bound how long it waits. A failure to start or a crash yields an outcome with no
16	//! components and one diagnostic, never an error; after [`MAX_RESTARTS`] crashes the checker stays down. A panic in
17	//! the checker counts as a crash: its session is not asked again, and a fresh one starts.
18	//!
19	//! What the checker holds is bounded by [`OnDemandConfig::max_rss_mib`] ([`Backend::memory_mib`]). Its memory is read
20	//! from its arenas, which leave out the host's (Node, Storybook), and it is never replaced: a closed session gives back
21	//! only part of its arenas, and a fresh one parses every file again, so a replacement raises what this process holds
22	//! (measured in `docs/gate-measurements.md`). Past the bound it stays down instead, and its components keep their
23	//! structural answer with a warning that says why.
24	//!
25	//! Requests wait in two queues: an interactive one (a story someone opened) is answered before any background one (a
26	//! warm-up, a fill, a prefetch), first come first served within each, and a background request a caller raised while
27	//! it waited moves to the interactive queue. So that background work is never starved, after [`INTERACTIVE_STREAK`]
28	//! interactive answers in a row while background requests wait, the oldest of them goes next.
29	
30	use std::collections::{BTreeSet, VecDeque};
31	use std::sync::atomic::{AtomicU32, Ordering};
32	use std::sync::{Arc, mpsc};
33	use std::thread::JoinHandle;
34	use std::time::{Duration, SystemTime};
35	
36	use caliper_docgen_core::types::semantic::{
37	    Delivery, Priority, SemanticOutcome, SemanticProvider, SemanticTarget, SharedPriority, SourceChange,
38	};
39	use caliper_docgen_core::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
40	use camino::Utf8PathBuf;
41	use rustc_hash::{FxHashMap, FxHashSet};
42	use tokio::sync::mpsc::error::TryRecvError;
43	use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender, unbounded_channel};
44	
45	use crate::checker::{Backend, Client};
46	use crate::rpc::{CallError, Rpc};
47	use crate::stamps::{self, Stamp};
48	use crate::{SemanticRequest, answer_on, group_by_file, root_files};
49	
50	/// How many files an unannounced-edit warning names before it counts the rest.
51	const UNTOLD_NAMED: usize = 5;
52	
53	/// Interactive answers in a row the checker gives while background requests wait, before the oldest background request
54	/// goes next: once first in its queue, a background request waits behind at most this many interactive ones.
55	const INTERACTIVE_STREAK: u32 = 4;
56	
57	/// Crashes the checker may have before it stays down for the session.
58	const MAX_RESTARTS: u32 = 3;
59	
60	/// What the checker may hold, in MiB, between requests, measured by its arenas: past it, it stops for the session. Its
61	/// arenas reached 46 MiB over 2,000 Chakra edits and 165 MiB over 937 Chakra and MUI components (single-component
62	/// programs peaked at 157 to 612 MiB in a `tsc` process); past this, it has loaded more than a story session needs.
63	const DEFAULT_MAX_RSS_MIB: u64 = 768;
64	
65	/// How many requests pass between memory checks: each reads the arenas' pages, which costs a few milliseconds. The
66	/// checker is also checked after its first program.
67	const RSS_CHECK_EVERY: u32 = 4;
68	
69	/// How long dropping a checker waits, by default, for its worker to finish a request and stop the checker, before leaving
70	/// the worker to finish on its own. Closing a session must not wait for a 60 s request.
71	const DEFAULT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
72	
73	/// How a warm [`OnDemand`] checker starts and is kept: where it runs, how long to wait on it, and what it may hold.
74	#[derive(Debug, Clone)]
75	pub struct OnDemandConfig {
76	    /// Where the checker finds `node_modules`: its working directory.
77	    pub project_root: Utf8PathBuf,
78	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
79	    pub tsconfig: Option<Utf8PathBuf>,
80	    /// Bound on each request to the checker.
81	    pub request_timeout: Duration,
82	    /// What the checker may hold, in MiB, read after a request from its arenas (the part of this process's memory the
83	    /// `tsrs` crates allocated): past it, the checker stops for the session, its components keeping their structural
84	    /// answer with a warning. A request that needs more finishes first: the bound is between requests, not inside one.
85	    pub max_rss_mib: u64,
86	    /// How long dropping the checker waits for a request in progress before it lets the worker finish alone, and how
87	    /// long a checker that panicked or went past its memory bound is given to close its session.
88	    pub shutdown_wait: Duration,
89	}
90	
91	impl OnDemandConfig {
92	    /// A configuration for `project_root` with a 60 second request timeout, a 768 MiB memory bound, a 5 second shutdown
93	    /// wait, and no explicit tsconfig.
94	    pub fn new(project_root: Utf8PathBuf) -> Self {
95	        Self {
96	            project_root,
97	            tsconfig: None,
98	            request_timeout: Duration::from_secs(60),
99	            max_rss_mib: DEFAULT_MAX_RSS_MIB,
100	            shutdown_wait: DEFAULT_SHUTDOWN_WAIT,
101	        }
102	    }
103	}
104	
105	/// How the snapshots a warm checker answered from were made.
106	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
107	pub struct Snapshots {
108	    /// Built from the disk with `createSnapshot`: the first request of a checker, one after a file changed that the
109	    /// checker was not told about, or one after a snapshot could not be listed or updated.
110	    pub created: u32,
111	    /// Brought up to date from the one before with `updateSnapshot`: announced edits re-read, the rest kept.
112	    pub updated: u32,
113	}
114	
115	/// What the worker thread reports about the checker, for the type that owns the thread to read.
116	#[derive(Default)]
117	struct Gauges {
118	    created: AtomicU32,
119	    updated: AtomicU32,
120	}
121	
122	enum Job {
123	    /// Start the checker now instead of at the first request.
124	    Warm,
125	    /// Files changed on disk; queued before any request that may read them.
126	    Changed(SourceChange),
127	    Answer(Asked),
128	    /// Tests only: the worker waits until this is released (or its sender dropped) before it takes another job, so a
129	    /// test can queue requests while the worker is busy and know they are all filed before one is picked.
130	    #[cfg(test)]
131	    Hold(mpsc::Receiver<()>),
132	}
133	
134	/// One request waiting for the checker.
135	struct Asked {
136	    targets: Vec<SemanticTarget>,
137	    priority: SharedPriority,
138	    delivery: Delivery,
139	}
140	
141	/// The requests waiting for the checker, in two queues by priority, first in first out within each. A request is
142	/// filed by its priority when it arrives and moved to the interactive queue when a caller raised it while it waited.
143	/// After [`INTERACTIVE_STREAK`] interactive requests in a row while the background queue is not empty, the next is
144	/// the oldest background request.
145	struct Queue<T> {
146	    interactive: VecDeque<(T, SharedPriority)>,
147	    background: VecDeque<(T, SharedPriority)>,
148	    /// Interactive requests taken in a row while a background one waited.
149	    streak: u32,
150	}
151	
152	impl<T> Default for Queue<T> {
153	    fn default() -> Self {
154	        Self { interactive: VecDeque::new(), background: VecDeque::new(), streak: 0 }
155	    }
156	}
157	
158	impl<T> Queue<T> {
159	    fn push(&mut self, item: T, priority: SharedPriority) {
160	        match priority.get() {
161	            Priority::Interactive => self.interactive.push_back((item, priority)),
162	            Priority::Background => self.background.push_back((item, priority)),
163	        }
164	    }
165	
166	    fn is_empty(&self) -> bool {
167	        self.interactive.is_empty() && self.background.is_empty()
168	    }
169	
170	    /// The request the checker answers next.
171	    fn next(&mut self) -> Option<T> {
172	        let (raised, waiting): (VecDeque<_>, VecDeque<_>) = std::mem::take(&mut self.background)
173	            .into_iter()
174	            .partition(|(_, priority)| priority.get() == Priority::Interactive);
175	        self.interactive.extend(raised);
176	        self.background = waiting;
177	        let starving = self.streak >= INTERACTIVE_STREAK;
178	        let (next, streak) = match (self.interactive.pop_front(), self.background.is_empty()) {
179	            (Some(interactive), true) => (Some(interactive), 0),
180	            (Some(interactive), false) if !starving => (Some(interactive), self.streak + 1),
181	            (Some(interactive), false) => {
182	                self.interactive.push_front(interactive);
183	                (self.background.pop_front(), 0)
184	            }
185	            (None, _) => (self.background.pop_front(), 0),
186	        };
187	        self.streak = streak;
188	        next.map(|(item, _)| item)
189	    }
190	}
191	
192	/// A warm checker that answers for the components it is asked about. Dropping it stops the checker.
193	pub struct OnDemand {
194	    jobs: Option<UnboundedSender<Job>>,
195	    thread: Option<JoinHandle<()>>,
196	    /// Receives once when the worker has stopped the checker and is about to exit.
197	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
198	    shutdown_wait: Duration,
199	    gauges: Arc<Gauges>,
200	}
201	
202	impl OnDemand {
203	    /// Starts the worker thread. The checker itself starts on the first request, or on [`OnDemand::warm_up`].
204	    pub fn new(config: OnDemandConfig) -> Self {
205	        let shutdown_wait = config.shutdown_wait;
206	        let (jobs, queue) = unbounded_channel();
207	        let (stopped_tx, stopped) = mpsc::channel();
208	        let gauges = Arc::new(Gauges::default());
209	        let worker_gauges = Arc::clone(&gauges);
210	        let thread = std::thread::Builder::new()
211	            .name("caliper-tsc".to_string())
212	            .spawn(move || {
213	                worker(config, queue, worker_gauges);
214	                stopped_tx.send(()).ok();
215	            })
216	            .ok();
217	        Self {
218	            jobs: thread.as_ref().map(|_| jobs),
219	            thread,
220	            stopped: std::sync::Mutex::new(Some(stopped)),
221	            shutdown_wait,
222	            gauges,
223	        }
224	    }
225	
226	    /// How many snapshots the answers so far came from, by how each was made.
227	    pub fn snapshots(&self) -> Snapshots {
228	        Snapshots {
229	            created: self.gauges.created.load(Ordering::Relaxed),
230	            updated: self.gauges.updated.load(Ordering::Relaxed),
231	        }
232	    }
233	
234	    /// Starts the checker in the background so the first request does not pay for it.
235	    pub fn warm_up(&self) {
236	        if let Some(jobs) = &self.jobs {
237	            jobs.send(Job::Warm).ok();
238	        }
239	    }
240	
241	    /// Tests only: holds the worker at its next job until the returned sender sends or is dropped (see [`Job::Hold`]).
242	    #[cfg(test)]
243	    fn hold(&self) -> mpsc::Sender<()> {
244	        let (release, held) = mpsc::channel();
245	        if let Some(jobs) = &self.jobs {
246	            jobs.send(Job::Hold(held)).ok();
247	        }
248	        release
249	    }
250	}
251	
252	impl SemanticProvider for OnDemand {
253	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
254	        let (reply, receiver) = mpsc::sync_channel(1);
255	        let delivery = Delivery::new(move |outcome| {
256	            // `None` drops the sender, which the receiver reads as a checker that stopped without answering.
257	            if let Some(outcome) = outcome {
258	                reply.send(outcome).ok();
259	            }
260	        });
261	        self.request_at(targets, SharedPriority::new(Priority::Interactive), delivery);
262	        receiver
263	    }
264	
265	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
266	        match &self.jobs {
267	            Some(jobs) => {
268	                if let Err(refused) = jobs.send(Job::Answer(Asked { targets, priority, delivery }))
269	                    && let Job::Answer(asked) = refused.0
270	                {
271	                    asked.delivery.deliver(Some(SemanticOutcome::unavailable("the checker thread has stopped")));
272	                }
273	            }
274	            None => delivery.deliver(Some(SemanticOutcome::unavailable("could not start the checker thread"))),
275	        }
276	    }
277	
278	    fn changed(&self, change: SourceChange) {
279	        if let Some(jobs) = &self.jobs {
280	            jobs.send(Job::Changed(change)).ok();
281	        }
282	    }
283	}
284	
285	impl Drop for OnDemand {
286	    fn drop(&mut self) {
287	        // Closing the queue ends the worker loop, which stops the checker before the thread exits. A worker still inside
288	        // a long request is left to finish it: the checker stops when it does, or with this process.
289	        self.jobs.take();
290	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
291	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
292	        if let Some(thread) = self.thread.take()
293	            && stopped
294	        {
295	            thread.join().ok();
296	        }
297	    }
298	}
299	
300	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
301	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
302	        Ok(runtime) => runtime,
303	        Err(error) => {
304	            let reason = format!("could not start an async runtime: {error}");
305	            while let Some(job) = queue.blocking_recv() {
306	                match job {
307	                    Job::Answer(asked) => asked.delivery.deliver(Some(SemanticOutcome::unavailable(reason.clone()))),
308	                    Job::Warm | Job::Changed(_) => {}
309	                    #[cfg(test)]
310	                    Job::Hold(_) => {}
311	                }
312	            }
313	            return;
314	        }
315	    };
316	    runtime.block_on(async move {
317	        let mut checker = Checker { gauges, ..Checker::default() };
318	        let mut waiting = Queue::default();
319	        let mut open = true;
320	        loop {
321	            // Every job sent so far is taken before the next request is picked, so the queues hold every request that
322	            // waits, and a change is applied before any request sent after it.
323	            if waiting.is_empty() && open {
324	                match queue.recv().await {
325	                    Some(job) => checker.take(&config, job, &mut waiting).await,
326	                    None => open = false,
327	                }
328	            }
329	            while open {
330	                match queue.try_recv() {
331	                    Ok(job) => checker.take(&config, job, &mut waiting).await,
332	                    Err(TryRecvError::Empty) => break,
333	                    Err(TryRecvError::Disconnected) => open = false,
334	                }
335	            }
336	            let Some(asked) = waiting.next() else {
337	                match open {
338	                    true => continue,
339	                    false => break,
340	                }
341	            };
342	            asked.delivery.deliver(Some(checker.answer(&config, asked.targets).await));
343	            // After the reply, so the caller never waits for the memory check or the replacement.
344	            checker.maintain(&config).await;
345	        }
346	        if let Some(backend) = checker.backend.take() {
347	            backend.shutdown().await;
348	        }
349	    });
350	}
351	
352	#[derive(Default)]
353	struct Checker {
354	    backend: Option<Backend>,
355	    /// Compiler options read once from the tsconfig for the running checker.
356	    options: Option<serde_json::Value>,
357	    restarts: u32,
358	    /// Requests the running checker has answered.
359	    served: u32,
360	    /// Why the checker cannot be used for the rest of the session.
361	    down: Option<String>,
362	    gauges: Arc<Gauges>,
363	    /// The snapshot the last request was answered from, kept for the next.
364	    live: Option<Live>,
365	    /// Files announced as changed since `live` was brought up to date.
366	    told: FxHashSet<Utf8PathBuf>,
367	}
368	
369	/// A snapshot kept between requests, and what its program read.
370	struct Live {
371	    rpc: Arc<Rpc>,
372	    /// The files its program is rooted at.
373	    roots: Vec<String>,
374	    /// When the files were compared with the disk, just before the snapshot was built or brought up to date.
375	    read_from: SystemTime,
376	    /// Every file the program read, as it was then; `None` until listed after the reply the snapshot built.
377	    stamps: Option<FxHashMap<Utf8PathBuf, Stamp>>,
378	}
379	
380	/// The warning an answer carries when files the snapshot read changed and the checker was not told.
381	fn untold_warning(files: &[Utf8PathBuf]) -> Diagnostic {
382	    let mut named: Vec<String> = files.iter().take(UNTOLD_NAMED).map(ToString::to_string).collect();
383	    if files.len() > UNTOLD_NAMED {
384	        named.push(format!("{} more", files.len() - UNTOLD_NAMED));
385	    }
386	    Diagnostic::new(
387	        DiagnosticSeverity::Warning,
388	        DiagnosticCode::SemanticBackend,
389	        format!(
390	            "the TypeScript checker was not told that {} changed; it read every file again for this answer",
391	            named.join(", ")
392	        ),
393	    )
394	    .with_help(
395	        "Whatever writes the project's files must tell the session (`update_file` or `ensure_fresh`); an edit the \
396	         checker is not told about is answered from the text it read before.",
397	    )
398	}
399	
400	impl Checker {
401	    /// Acts on a job as it arrives: starts the process, applies a change, or files a request by its priority.
402	    async fn take(&mut self, config: &OnDemandConfig, job: Job, waiting: &mut Queue<Asked>) {
403	        match job {
404	            Job::Warm => {
405	                self.ensure(config).await.ok();
406	            }
407	            Job::Changed(change) => self.told(change).await,
408	            Job::Answer(asked) => {
409	                let priority = asked.priority.clone();
410	                waiting.push(asked, priority);
411	            }
412	            #[cfg(test)]
413	            Job::Hold(released) => {
414	                released.recv().ok();
415	            }
416	        }
417	    }
418	
419	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
420	        if let Some(reason) = &self.down {
421	            return Err(reason.clone());
422	        }
423	        if self.backend.as_ref().is_some_and(|backend| !backend.is_alive()) {
424	            if let Some(dead) = self.backend.take() {
425	                dead.shutdown_within(config.shutdown_wait).await;
426	            }
427	            self.options = None;
428	            self.live = None;
429	            self.told.clear();
430	            self.restarts += 1;
431	            if self.restarts > MAX_RESTARTS {
432	                return Err(self.stay_down("the checker kept crashing".to_string()));
433	            }
434	        }
435	        if self.backend.is_none() {
436	            let backend = Backend::start(&config.project_root, 1).map_err(|reason| self.stay_down(reason))?;
437	            // A checker started after a crash counts its own programs.
438	            self.served = 0;
439	            // Initialize the session and read the compiler options once; every request after builds only its program.
440	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
441	            match Rpc::prepare(&backend.client(), config.request_timeout, tsconfig).await {
442	                Ok(options) => self.options = Some(options),
443	                Err(error) => {
444	                    backend.shutdown().await;
445	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
446	                }
447	            }
448	            self.backend = Some(backend);
449	        }
450	        Ok(())
451	    }
452	
453	    fn stay_down(&mut self, reason: String) -> String {
454	        self.down = Some(reason.clone());
455	        reason
456	    }
457	
458	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
459	        if let Err(reason) = self.ensure(config).await {
460	            return SemanticOutcome::unavailable(reason);
461	        }
462	        let Some(backend) = self.backend.as_ref() else {
463	            return SemanticOutcome::unavailable("the checker is not running");
464	        };
465	        let client = backend.client();
466	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
467	        request.tsconfig = config.tsconfig.clone();
468	        request.request_timeout = config.request_timeout;
469	        let roots = root_files(&request);
470	        if roots.is_empty() {
471	            return group_by_file(&request).0;
472	        }
473	        let answered = match self.snapshot_for(client, config.request_timeout, roots.clone()).await {
474	            Ok((rpc, warning)) => answer_on(std::slice::from_ref(&rpc), &request, &roots).await.map(|mut outcome| {
475	                outcome.diagnostics.extend(warning);
476	                outcome
477	            }),
478	            Err(error) => Err(error),
479	        };
480	        self.served += 1;
481	        match answered {
482	            Ok(outcome) => outcome,
483	            Err(error) => {
484	                self.forget().await;
485	                SemanticOutcome::unavailable(format!("the checker stopped answering: {error}"))
486	            }
487	        }
488	    }
489	
490	    /// The snapshot to answer from, its program rooted at `roots`: the kept one brought up to date with the files the
491	    /// checker was told about, or a fresh one when none is kept, the kept one cannot be checked or updated, or a file
492	    /// it read changed with nobody telling the checker. The last comes with a warning that names the files.
493	    async fn snapshot_for(
494	        &mut self,
495	        client: Client,
496	        deadline: Duration,
497	        roots: Vec<String>,
498	    ) -> Result<(Arc<Rpc>, Option<Diagnostic>), CallError> {
499	        let read_from = SystemTime::now();
500	        let told = std::mem::take(&mut self.told);
501	        let mut warning = None;
502	        if let Some(live) = self.live.take() {
503	            if let Some(stamps) = &live.stamps {
504	                let drift = stamps::drift(stamps, &told);
505	                if drift.untold.is_empty() {
506	                    let reread: BTreeSet<Utf8PathBuf> = told.into_iter().chain(drift.unsure).collect();
507	                    if reread.is_empty() && live.roots == roots {
508	                        let rpc = live.rpc.clone();
509	                        self.live = Some(live);
510	                        return Ok((rpc, None));
511	                    }
512	                    let (changed, deleted): (Vec<String>, Vec<String>) = {
513	                        let (present, gone): (Vec<_>, Vec<_>) = reread.into_iter().partition(|file| file.exists());
514	                        (present.into_iter().map(String::from).collect(), gone.into_iter().map(String::from).collect())
515	                    };
516	                    let rerooted = (live.roots != roots).then_some(roots.as_slice());
517	                    match live.rpc.updated(&changed, &deleted, rerooted).await {
518	                        Ok(rpc) => {
519	                            live.rpc.release().await;
520	                            let rpc = Arc::new(rpc);
521	                            self.gauges.updated.fetch_add(1, Ordering::Relaxed);
522	                            self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
523	                            return Ok((rpc, None));
524	                        }
525	                        Err(CallError::Rejected(message)) => {
526	                            tracing::debug!(%message, "the checker could not update its snapshot; building a fresh one");
527	                        }
528	                        Err(fatal) => {
529	                            // The kept snapshot is no longer held anywhere else: release it before giving up on it.
530	                            live.rpc.release().await;
531	                            return Err(fatal);
532	                        }
533	                    }
534	                } else {
535	                    tracing::warn!(files = ?drift.untold, "files changed that the checker was not told about");
536	                    warning = Some(untold_warning(&drift.untold));
537	                }
538	            }
539	            live.rpc.release().await;
540	        }
541	        let options = self.options.as_ref().ok_or_else(|| CallError::Fatal("the checker is not initialized".into()))?;
542	        let rpc = Arc::new(Rpc::open_with(client, deadline, options, &roots, false).await?);
543	        self.gauges.created.fetch_add(1, Ordering::Relaxed);
544	        self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
545	        Ok((rpc, warning))
546	    }
547	
548	    /// Files changed on disk: the kept snapshot reads them again at the next request, or, when anything may have
549	    /// changed, is dropped.
550	    async fn told(&mut self, change: SourceChange) {
551	        match change {
552	            SourceChange::Files(files) if self.live.is_some() => self.told.extend(files),
553	            SourceChange::Files(_) => {}
554	            SourceChange::Everything => self.forget().await,
555	        }
556	    }
557	
558	    /// Drops the kept snapshot, so the next request builds one from the disk.
559	    async fn forget(&mut self) {
560	        self.told.clear();
561	        if let Some(live) = self.live.take() {
562	            live.rpc.release().await;
563	        }
564	    }
565	
566	    /// Lists and stamps the files the kept snapshot's program read, once, after the reply it answered, so the first
567	    /// answer does not wait for it. A snapshot that cannot be listed cannot be checked, and is dropped.
568	    async fn stamp(&mut self) {
569	        let Some(live) = self.live.as_mut().filter(|live| live.stamps.is_none()) else { return };
570	        match live.rpc.source_file_names().await {
571	            Ok(files) => {
572	                live.stamps = Some(stamps::record(files.into_iter().map(Utf8PathBuf::from).collect(), live.read_from))
573	            }
574	            Err(error) => {
575	                tracing::debug!(%error, "could not list the snapshot's files; the next request builds a fresh one");
576	                self.forget().await;
577	            }
578	        }
579	    }
580	
581	    /// Stops the checker for the session past the memory bound (see [`Upkeep`]), and otherwise stamps the snapshot it
582	    /// keeps.
583	    async fn maintain(&mut self, config: &OnDemandConfig) {
584	        let Some(backend) = self.backend.as_ref() else { return };
585	        let held = Upkeep::checks_memory(self.served).then(|| backend.memory_mib()).flatten();
586	        let upkeep = Upkeep::decide(held, config.max_rss_mib);
587	        if upkeep == Upkeep::Down {
588	            let mib = held.unwrap_or_default();
589	            tracing::warn!(
590	                held_mib = mib,
591	                bound_mib = config.max_rss_mib,
592	                "the built-in checker is past its memory bound"
593	            );
594	            self.live = None;
595	            self.told.clear();
596	            if let Some(old) = self.backend.take() {
597	                old.shutdown_within(config.shutdown_wait).await;
598	            }
599	            self.options = None;
600	            self.stay_down(format!(
601	                "the built-in checker held {mib} MiB, more than its {} MiB bound (`max_rss_mib`), and this process \
602	                 keeps that memory, so components keep their structural answer for the rest of the session",
603	                config.max_rss_mib
604	            ));
605	            return;
606	        }
607	        self.stamp().await;
608	    }
609	}
610	
611	/// What becomes of a checker after a reply.
612	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
613	enum Upkeep {
614	    /// It keeps answering.
615	    Keep,
616	    /// The checker holds more than the memory bound, which a replacement would not give back: it stays down for the
617	    /// session.
618	    Down,
619	}
620	
621	impl Upkeep {
622	    /// Whether to read what the checker holds after its `served`th program: the first, so that one program past the
623	    /// bound is caught at once, and every [`RSS_CHECK_EVERY`]th.
624	    fn checks_memory(served: u32) -> bool {
625	        served == 1 || served.is_multiple_of(RSS_CHECK_EVERY)
626	    }
627	
628	    fn decide(held_mib: Option<u64>, bound_mib: u64) -> Upkeep {
629	        if held_mib.is_some_and(|mib| mib > bound_mib) { Upkeep::Down } else { Upkeep::Keep }
630	    }
631	}
632	
633	#[cfg(test)]
634	mod tests {
635	    #![allow(clippy::unwrap_used, clippy::expect_used)]
636	
637	    use std::time::Duration;
638	
639	    use caliper_docgen_core::pipeline::{PipelineOptions, extract};
640	    use caliper_docgen_core::types::semantic::{Delivery, Priority, SemanticProvider, SharedPriority};
641	    use camino::Utf8PathBuf;
642	
643	    use super::{OnDemand, OnDemandConfig};
644	
645	    use super::{INTERACTIVE_STREAK, Queue, RSS_CHECK_EVERY, Upkeep};
646	
647	    /// A story asked while background requests wait is answered before them. The worker is held until all four are
648	    /// queued ([`OnDemand::hold`]); it then files every queued job before it picks one, so the order does not depend on
649	    /// how fast the test thread queues them. The answers arrive in the order the one worker gives them.
650	    #[test]
651	    fn a_story_asked_behind_queued_background_requests_is_answered_before_them() {
652	        let dir = tempfile::Builder::new().prefix("OnDemand").tempdir().unwrap();
653	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
654	        let fixtures = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/project");
655	        for name in ["Button.tsx", "tsconfig.json"] {
656	            std::fs::copy(fixtures.join(name), root.join(name)).unwrap();
657	        }
658	        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
659	        let target = |name: &str| crate::targets_of(&output).into_iter().find(|t| t.display_name == name).unwrap();
660	        let checker = OnDemand::new(OnDemandConfig::new(root.clone()));
661	        let (sender, answered) = std::sync::mpsc::channel();
662	        let queue = |name: &'static str, priority: Priority| {
663	            let sender = sender.clone();
664	            let delivery = Delivery::new(move |outcome| {
665	                sender.send((name, outcome)).ok();
666	            });
667	            checker.request_at(vec![target(name)], SharedPriority::new(priority), delivery);
668	        };
669	
670	        let release = checker.hold();
671	        for _ in 0..3 {
672	            queue("Button", Priority::Background);
673	        }
674	        queue("Other", Priority::Interactive);
675	        release.send(()).unwrap();
676	
677	        let order: Vec<&str> = (0..4)
678	            .map(|_| {
679	                let (name, outcome) = answered.recv_timeout(Duration::from_secs(60)).expect("an answer");
680	                let outcome = outcome.expect("the checker answered");
681	                assert_eq!(outcome.components.len(), 1, "{name}: {:?}", outcome.diagnostics);
682	                name
683	            })
684	            .collect();
685	
686	        assert_eq!(order, ["Other", "Button", "Button", "Button"]);
687	    }
688	
689	    #[test]
690	    fn the_checker_stops_past_the_bound_and_keeps_answering_within_it() {
691	        assert_eq!(Upkeep::decide(Some(100), 768), Upkeep::Keep);
692	        assert_eq!(Upkeep::decide(None, 768), Upkeep::Keep);
693	        assert_eq!(Upkeep::decide(Some(768), 768), Upkeep::Keep);
694	        assert_eq!(Upkeep::decide(Some(800), 768), Upkeep::Down);
695	    }
696	
697	    #[test]
698	    fn the_checker_is_read_after_its_first_program_and_every_fourth() {
699	        assert_eq!(RSS_CHECK_EVERY, 4);
700	        let read = (1..=9).filter(|served| Upkeep::checks_memory(*served)).collect::<Vec<_>>();
701	        assert_eq!(read, [1, 4, 8]);
702	        assert!(Upkeep::checks_memory(64));
703	    }
704	
705	    fn drain(queue: &mut Queue<&'static str>) -> Vec<&'static str> {
706	        std::iter::from_fn(|| queue.next()).collect()
707	    }
708	
709	    fn push(queue: &mut Queue<&'static str>, item: &'static str, priority: Priority) -> SharedPriority {
710	        let priority = SharedPriority::new(priority);
711	        queue.push(item, priority.clone());
712	        priority
713	    }
714	
715	    #[test]
716	    fn an_interactive_request_goes_before_every_background_one_and_each_queue_keeps_its_order() {
717	        let mut queue = Queue::default();
718	        push(&mut queue, "fill 1", Priority::Background);
719	        push(&mut queue, "fill 2", Priority::Background);
720	        push(&mut queue, "story 1", Priority::Interactive);
721	        push(&mut queue, "fill 3", Priority::Background);
722	        push(&mut queue, "story 2", Priority::Interactive);
723	
724	        assert_eq!(drain(&mut queue), ["story 1", "story 2", "fill 1", "fill 2", "fill 3"]);
725	    }
726	
727	    #[test]
728	    fn a_background_request_raised_while_it_waits_goes_with_the_interactive_ones() {
729	        let mut queue = Queue::default();
730	        push(&mut queue, "fill 1", Priority::Background);
731	        let prefetch = push(&mut queue, "prefetch of the story", Priority::Background);
732	        push(&mut queue, "story", Priority::Interactive);
733	
734	        prefetch.raise();
735	
736	        assert_eq!(drain(&mut queue), ["story", "prefetch of the story", "fill 1"]);
737	    }
738	
739	    #[test]
740	    fn a_waiting_background_request_goes_after_a_bounded_run_of_interactive_ones() {
741	        assert_eq!(INTERACTIVE_STREAK, 4);
742	        let mut queue = Queue::default();
743	        push(&mut queue, "fill 1", Priority::Background);
744	        push(&mut queue, "fill 2", Priority::Background);
745	        for story in ["story 1", "story 2", "story 3", "story 4", "story 5", "story 6", "story 7", "story 8", "story 9"]
746	        {
747	            push(&mut queue, story, Priority::Interactive);
748	        }
749	
750	        assert_eq!(
751	            drain(&mut queue),
752	            [
753	                "story 1", "story 2", "story 3", "story 4", "fill 1", "story 5", "story 6", "story 7", "story 8",
754	                "fill 2", "story 9"
755	            ]
756	        );
757	    }
758	
759	    #[test]
760	    fn interactive_requests_with_no_background_waiting_do_not_count_toward_the_bound() {
761	        let mut queue = Queue::default();
762	        for story in ["story 1", "story 2", "story 3", "story 4", "story 5"] {
763	            push(&mut queue, story, Priority::Interactive);
764	            assert_eq!(queue.next(), Some(story));
765	        }
766	        push(&mut queue, "fill", Priority::Background);
767	        push(&mut queue, "story 6", Priority::Interactive);
768	
769	        assert_eq!(drain(&mut queue), ["story 6", "fill"]);
770	    }
