45	/// How many files are asked about at once, shared among the programs. A program's checker answers requests one at a
46	/// time; this keeps it from idling between them.
47	const FILES_IN_FLIGHT: usize = 16;
48	
49	/// The most threads the whole-project run converts the checker's answers on: past four, the checker's own thread is
50	/// the bound (measured on Chakra's components, docs/gate-measurements.md).
51	const CONVERTER_THREADS: usize = 4;
52	
53	/// How many programs a whole-project run asks at once, each on a thread of the linked checker: a program's requests are
54	/// answered one at a time, and the checker's answering is what bounds the run (docs/gate-measurements.md).
55	const CHECKER_PROGRAMS: usize = 2;
56	
57	/// The fewest files a program answers for: a project smaller than this asks one program, which builds no second checker
58	/// for a handful of components.
59	const MIN_FILES_PER_PROGRAM: usize = 32;
60	
61	/// A component the structural pass found.
62	pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;
63	
64	/// The components of `output`, in output order.
65	pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
66	    output
67	        .components
68	        .iter()
69	        .map(|(key, entry)| Target {
70	            key: key.clone(),
71	            file_path: entry.file_path.clone(),
72	            display_name: entry.display_name.clone(),
73	            exports: entry.exports.clone(),
74	            described: entry
75	                .props
76	                .values()
77	                .filter(|prop| !prop.description.is_empty())
78	                .map(|prop| prop.name.clone())
79	                .collect(),
80	            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
81	            react_wanted: Some(Default::default()),
82	        })
83	        .collect()
84	}
