86	/// One whole-project request to the checker: the components to answer for, and how to ask. Built with
87	/// [`SemanticRequest::new`] and answered by [`resolve`].
88	#[derive(Debug, Clone)]
89	pub struct SemanticRequest {
90	    /// Where the checker finds `node_modules`: its working directory.
91	    pub project_root: Utf8PathBuf,
92	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
93	    pub tsconfig: Option<Utf8PathBuf>,
94	    /// The components to ask about.
95	    pub targets: Vec<Target>,
96	    /// Bound on each request.
97	    pub request_timeout: Duration,
98	    /// Write every request and its answer here as JSON; the tests read it to count and inspect the calls a run makes.
99	    pub record_to: Option<Utf8PathBuf>,
100	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
101	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
102	    pub reverse_queries: bool,
103	}
104	
105	impl SemanticRequest {
106	    /// A request for `targets` under `project_root`, with a 60 second timeout and no tsconfig.
107	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
108	        Self {
109	            project_root,
110	            tsconfig: None,
111	            targets,
112	            request_timeout: Duration::from_secs(60),
113	            record_to: None,
114	            reverse_queries: false,
115	        }
116	    }
117	}
118	
119	/// Resolves the request's components with the checker. Blocks; builds its own runtime, so it must not be called from
120	/// inside one. The runtime has up to four threads: the built-in checker answers two programs at once, each on a thread
121	/// of its own, and while it does, the answers it gave the other files in flight are read and converted on these.
122	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
123	    let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
124	    let built = tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build();
125	    let runtime = match built {
126	        Ok(runtime) => runtime,
127	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
128	    };
129	    runtime.block_on(run(request, None))
130	}
131	
132	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
133	/// the checker cannot be asked about.
134	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
135	    let mut outcome = SemanticOutcome::default();
136	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
137	    let mut order: Vec<&Utf8Path> = Vec::new();
138	    for target in &request.targets {
139	        if target.exports.is_empty() {
140	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
141	            continue;
142	        }
143	        let group = by_file.entry(target.file_path.as_path()).or_default();
144	        if group.is_empty() {
145	            order.push(target.file_path.as_path());
146	        }
147	        group.push(target);
148	    }
149	    (outcome, by_file, order)
150	}
151	
152	/// Answers `request` with a checker started for it, asking `programs` programs at once, or by default as many as
153	/// [`CHECKER_PROGRAMS`] and the files allow ([`MIN_FILES_PER_PROGRAM`]).
154	async fn run(request: SemanticRequest, programs: Option<usize>) -> SemanticOutcome {
155	    if request.targets.iter().all(|target| target.exports.is_empty()) {
156	        return group_by_file(&request).0;
157	    }
158	    let files = group_by_file(&request).2.len();
159	    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
160	    let checker = match Backend::start(&request.project_root, programs) {
161	        Ok(checker) => checker,
162	        Err(reason) => return SemanticOutcome::unavailable(reason),
163	    };
164	    let outcome = answer_with(&checker, &request).await;
165	    checker.shutdown().await;
166	    outcome
167	}
168	
169	/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
170	fn root_files(request: &SemanticRequest) -> Vec<String> {
171	    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
172	}
173	
174	/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
175	/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
176	async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
177	    let files = root_files(request);
178	    if files.is_empty() {
179	        return group_by_file(request).0;
180	    }
181	    let started = std::time::Instant::now();
182	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
183	    let count = checker.parallel_programs();
184	    let record = request.record_to.is_some();
185	    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
186	    let programs: Vec<Arc<Rpc>> = match opened {
187	        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
188	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
189	    };
190	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, programs = count, "semantic program built");
191	    let answered = answer_on(&programs, request, &files).await;
192	    if let Some(first) = programs.first() {
193	        first.release().await;
194	    }
195	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
196	}
197	
198	/// Answers the request's targets on a snapshot whose programs are each rooted at `files` ([`root_files`]), one session
199	/// bound to each: a file is answered by one of them, the `n`th file by the `n % programs.len()`th. Each program has its
200	/// checker and its handles, so each has its own [`Converter`]; since every program holds the same files, each answers
201	/// a component as any other would, and the output does not depend on how the files are shared out. The snapshot is
202	/// left as it is, for the caller to keep or release.
203	async fn answer_on(
204	    programs: &[Arc<Rpc>],
205	    request: &SemanticRequest,
206	    files: &[String],
207	) -> Result<SemanticOutcome, CallError> {
208	    let (mut outcome, by_file, order) = group_by_file(request);
209	    let mut answered = session(programs, request, files, &by_file, &order).await?;
210	    outcome.components.append(&mut answered.components);
211	    outcome.fallbacks.append(&mut answered.fallbacks);
212	    Ok(outcome)
213	}
214	
215	async fn session(
216	    programs: &[Arc<Rpc>],
217	    request: &SemanticRequest,
218	    files: &[String],
219	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
220	    order: &[&Utf8Path],
221	) -> Result<SemanticOutcome, CallError> {
222	    let started = std::time::Instant::now();
223	    let Some(rpc) = programs.first() else { return Ok(SemanticOutcome::default()) };
224	    let converters: Vec<Converter> =
225	        programs.iter().map(|program| Converter::new(program.clone(), request.reverse_queries)).collect();
226	    let interner = Arc::new(PropInterner::default());
227	    // The files in order; each worker takes the next one when it is done with its last, so a program whose files take
228	    // longer answers fewer of them.
229	    let queue: VecDeque<Vec<Target>> = order
230	        .iter()
231	        .map(|file| by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect())
232	        .collect();
233	    let queue = Arc::new(Mutex::new(queue));
234	
235	    let mut tasks = JoinSet::new();
236	    for worker in 0..FILES_IN_FLIGHT {
237	        let lane = worker % programs.len();
238	        let (Some(rpc), Some(converter)) = (programs.get(lane), converters.get(lane)) else { continue };
239	        let (rpc, converter, queue, interner) = (rpc.clone(), converter.clone(), queue.clone(), interner.clone());
240	        tasks.spawn(async move {
241	            let mut answered = (SemanticOutcome::default(), Vec::new());
242	            loop {
243	                let next = queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner).pop_front();
244	                let Some(targets) = next else { return Ok(answered) };
245	                let (mut outcome, mut generic) = answer_file(&rpc, &converter, &interner, targets).await?;
246	                answered.0.components.append(&mut outcome.components);
247	                answered.0.fallbacks.append(&mut outcome.fallbacks);
248	                answered.1.append(&mut generic);
249	            }
250	        });
251	    }
252	
253	    let mut outcome = SemanticOutcome::default();
254	    let mut generic = Vec::new();
255	    let mut failure = None;
256	    while let Some(joined) = tasks.join_next().await {
257	        match joined {
258	            Ok(Ok((mut answered, mut instantiations))) => {
259	                outcome.components.append(&mut answered.components);
260	                outcome.fallbacks.append(&mut answered.fallbacks);
261	                generic.append(&mut instantiations);
262	            }
263	            Ok(Err(error)) => {
264	                failure = Some(error);
265	                tasks.abort_all();
266	            }
267	            // A panic inside a worker must not silently leave its components structural.
268	            Err(joined) if joined.is_panic() => {
269	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
270	                tasks.abort_all();
271	            }
272	            // A cancelled task is one this loop aborted after a failure.
273	            Err(_cancelled) => {}
274	        }
275	    }
276	    if let Some(error) = failure {
277	        return Err(error);
278	    }
279	    if !generic.is_empty() {
280	        let mut instantiated =
281	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
282	        outcome.components.append(&mut instantiated.components);
283	        outcome.fallbacks.append(&mut instantiated.fallbacks);
284	    }
285	
286	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
287	        && let Ok(json) = serde_json::to_string_pretty(&recording)
288	        && let Err(error) = std::fs::write(path, json)
289	    {
290	        tracing::warn!("could not write the recording to {path}: {error}");
291	    }
292	    tracing::debug!(
293	        requests = ?rpc.calls(),
294	        files = files.len(),
295	        type_memo = ?converters.iter().map(Converter::memo_stats).fold((0, 0), |sum, (hits, misses)| (sum.0 + hits, sum.1 + misses)),
296	        total_ms = started.elapsed().as_millis() as u64,
297	        "semantic backend finished"
298	    );
299	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
300	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
301	    Ok(outcome)
302	}
303	
304	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
305	    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
306	}
307	
308	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
309	/// generic components come back apart, to be answered from their instantiations once every file is done.
310	async fn answer_file(
311	    rpc: &Rpc,
312	    converter: &Converter,
313	    interner: &PropInterner,
314	    targets: Vec<Target>,
315	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
316	    let mut outcome = SemanticOutcome::default();
317	    let mut generic = Vec::new();
318	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
319	    let module = match module_exports(rpc, first.file_path.as_str()).await {
320	        Ok(Some(module)) => module,
321	        Ok(None) | Err(CallError::Rejected(_)) => {
322	            outcome
323	                .fallbacks
324	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
325	            return Ok((outcome, generic));
326	        }
327	        Err(fatal) => return Err(fatal),
328	    };
329	
330	    for target in &targets {
331	        let requests = Arc::new(AtomicU64::new(0));
332	        let started = std::time::Instant::now();
333	        let answered =
334	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
335	        tracing::debug!(
336	            component = %target.display_name,
337	            requests = requests.load(Ordering::Relaxed),
338	            ms = started.elapsed().as_millis() as u64,
339	            "semantic component answered"
340	        );
341	        match answered {
342	            Ok(Answer::Props(component::Props { props, composes })) => {
343	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes });
344	            }
345	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
346	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
347	            Err(CallError::Rejected(message)) => {
348	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
349	            }
350	            Err(fatal) => return Err(fatal),
351	        }
352	    }
353	    Ok((outcome, generic))
354	}
355	
356	/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
357	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
358	    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
359	    let exports = rpc.exports_of_module(&symbol.reference).await?;
360	    Ok(Some(component::Module { symbol, exports }))
361	}
