363	#[cfg(test)]
364	mod tests {
365	    #![allow(clippy::unwrap_used, clippy::panic)]
366	
367	    use caliper_docgen_core::pipeline::{PipelineOptions, extract};
368	
369	    use super::*;
370	
371	    /// A project of `files` components over shared types (a union, an interface base, an `Omit` in an intersection, a
372	    /// recursive alias) whose props all extend an interface the last file augments (`declare global`).
373	    fn shared_types_project(files: usize) -> (tempfile::TempDir, Utf8PathBuf) {
374	        let dir = tempfile::Builder::new().prefix("Programs").tempdir().unwrap();
375	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
376	        std::fs::write(
377	            root.join("types.ts"),
378	            "export type Size = 'sm' | 'md' | 'lg';\n\
379	             export interface Base {\n  /** The id. */\n  id: string;\n  size?: Size;\n}\n\
380	             export type Tree = { label: string; children?: Tree[] };\n\
381	             export type Styled = Omit<Base, 'id'> & { tone?: 'a' | 'b'; onPick?: (value: Size) => void };\n\
382	             declare global { interface Augmented { fromTypes?: number } }\n",
383	        )
384	        .unwrap();
385	        for index in 0..files {
386	            let augments = if index + 1 == files {
387	                "declare global { interface Augmented { fromLastFile?: boolean } }\n"
388	            } else {
389	                ""
390	            };
391	            std::fs::write(
392	                root.join(format!("C{index}.tsx")),
393	                format!(
394	                    "import type {{ Base, Styled, Tree }} from './types';\n{augments}\
395	                     export interface C{index}Props extends Base, Augmented {{ own{index}: number; tree?: Tree; styled: Styled }}\n\
396	                     export function C{index}(props: C{index}Props) {{ return null; }}\n"
397	                ),
398	            )
399	            .unwrap();
400	        }
401	        (dir, root)
402	    }
403	
404	    fn answered(root: &Utf8Path, programs: usize) -> SemanticOutcome {
405	        let output = extract(&PipelineOptions { src_dirs: vec![root.to_owned()], ..PipelineOptions::default() });
406	        let request = SemanticRequest::new(root.to_owned(), targets_of(&output));
407	        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
408	        runtime.block_on(run(request, Some(programs)))
409	    }
410	
411	    /// Three programs on the built-in checker, each answering some of the files, give the answer one program gives:
412	    /// each holds every root file, so what one file declares (here a global augmentation in the last) reaches the
413	    /// components the other programs answer.
414	    #[test]
415	    fn several_programs_answer_as_one_does() {
416	        let (_dir, root) = shared_types_project(9);
417	
418	        let one = answered(&root, 1);
419	        let three = answered(&root, 3);
420	
421	        assert!(one.diagnostics.is_empty() && one.fallbacks.is_empty(), "{one:?}");
422	        assert_eq!(one.components.len(), 9);
423	        for component in &one.components {
424	            let names: Vec<&str> = component.props.iter().map(|prop| prop.name.as_str()).collect();
425	            assert!(names.contains(&"fromLastFile") && names.contains(&"fromTypes"), "{names:?}");
426	        }
427	        assert_eq!(one, three);
428	    }
429	
430	    /// Stands in for the built-in checker's session: it initializes and makes a snapshot of as many programs as asked,
431	    /// and panics on any question about them, counting how many it was asked.
432	    struct Panicking {
433	        asked: Arc<std::sync::atomic::AtomicU32>,
434	    }
435	
436	    impl checker::Served for Panicking {
437	        fn handle(&self, method: &str, params: &[u8]) -> Result<String, checker::Failure> {
438	            match method {
439	                "initialize" | "release" => Ok("null".to_string()),
440	                "createSnapshot" => {
441	                    let params: serde_json::Value = serde_json::from_slice(params).unwrap();
442	                    let count = params["createPrograms"].as_array().map_or(1, Vec::len);
443	                    let projects: Vec<_> = (0..count).map(|n| serde_json::json!({ "id": format!("p{n}") })).collect();
444	                    Ok(serde_json::json!({ "snapshot": 1, "projects": projects }).to_string())
445	                }
446	                _ => {
447	                    self.asked.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
448	                    panic!("checker invariant broken")
449	                }
450	            }
451	        }
452	
453	        fn discard(&self, _method: &str, _answer: &str) {}
454	
455	        fn close(&self) {}
456	    }
457	
458	    /// A whole-project run on two lanes whose checker panics: the lane that met it fails its file, the other lane
459	    /// stops, and the run gives every component its structural answer with one diagnostic, never a partial answer.
460	    #[test]
461	    fn a_panic_on_one_lane_fails_the_whole_run_to_the_structural_answer() {
462	        let (_dir, root) = shared_types_project(6);
463	        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
464	        let request = SemanticRequest::new(root.clone(), targets_of(&output));
465	        let asked = Arc::new(std::sync::atomic::AtomicU32::new(0));
466	        let session = Panicking { asked: Arc::clone(&asked) };
467	        let checker = Backend::spawn(2, move || session).unwrap();
468	        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
469	
470	        let outcome = runtime.block_on(answer_with(&checker, &request));
471	
472	        assert!(outcome.components.is_empty(), "{:?}", outcome.components);
473	        assert_eq!(outcome.diagnostics.len(), 1, "{:?}", outcome.diagnostics);
474	        let message = &outcome.diagnostics[0].message;
475	        // Whichever lane's error the run meets first: the panic, the other lane's refusal after it, or a request that
476	        // was still queued on a lane that stopped.
477	        let reason = message.strip_prefix("TypeScript checker backend unavailable: the checker stopped answering: ");
478	        assert!(
479	            reason.is_some_and(|reason| [
480	                "panic: checker invariant broken",
481	                "the built-in checker stopped: a panic unwound through its session",
482	                "session shut down",
483	            ]
484	            .iter()
485	            .any(|said| reason.contains(said))),
486	            "{message}"
487	        );
488	        // Each lane met the panic at most once: none was asked again after it.
489	        assert!((1..=2).contains(&asked.load(std::sync::atomic::Ordering::Relaxed)));
490	        assert!(!checker.is_alive());
491	        runtime.block_on(checker.shutdown());
492	    }
493	
494	    /// A prop the converter keeps for later components is kept by what makes it, including which of its JSDoc was
495	    /// asked: a component whose structural pass already described `id` is not handed the description another asked for,
496	    /// and the one after it is not handed an empty one. The three are in one file, so they are answered in turn and the
497	    /// later ones find the first one's props kept.
498	    #[test]
499	    fn a_kept_prop_is_one_made_by_the_same_question() {
500	        let (_dir, root) = shared_types_project(0);
501	        let component = |name: &str| {
502	            format!(
503	                "export interface {name}Props extends Base {{ own: number }}\nexport function {name}(props: {name}Props) {{ return null; }}\n"
504	            )
505	        };
506	        let text = format!(
507	            "import type {{ Base }} from './types';\n{}{}{}",
508	            component("C0"),
509	            component("C1"),
510	            component("C2")
511	        );
512	        std::fs::write(root.join("All.tsx"), text).unwrap();
513	        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
514	        let mut targets = targets_of(&output);
515	        for target in &mut targets {
516	            target.described.clear();
517	        }
518	        if let Some(target) = targets.iter_mut().find(|target| target.key == "C1") {
519	            target.described.insert("id".to_string());
520	        }
521	        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
522	
523	        let outcome = runtime.block_on(run(SemanticRequest::new(root.clone(), targets), Some(1)));
524	
525	        let description = |key: &str| {
526	            let component = outcome.components.iter().find(|component| component.key == key).unwrap();
527	            component.props.iter().find(|prop| prop.name == "id").unwrap().description.clone()
528	        };
529	        assert_eq!(
530	            (description("C0"), description("C1"), description("C2")),
531	            ("The id.".into(), String::new(), "The id.".into())
532	        );
533	    }
534	}
