1	//! What the files a warm checker's snapshot read looked like on disk, so that an edit it was not told about is found
2	//! before it answers from them (ADR 0026 S6).
3	//!
4	//! The checker keeps every file a snapshot read and reads one again only when it is told the file changed: an edit it
5	//! is not told about is answered from the old text, with no sign. A stamp is a file's modification time and length as
6	//! the snapshot read it, taken when the snapshot was built; before the next answer every stamp is taken again and
7	//! compared. A file modified within [`MTIME_GRANULARITY`] of the build cannot be told apart from a later edit by its
8	//! stamp, so it is unsure and is read again at every update until it settles.
9	
10	use std::time::{Duration, SystemTime};
11	
12	use camino::{Utf8Path, Utf8PathBuf};
13	use rustc_hash::{FxHashMap, FxHashSet};
14	
15	/// Filesystems that keep modification times to the second, or to a kernel clock tick, give an edit made just after a
16	/// read the same modification time.
17	const MTIME_GRANULARITY: Duration = Duration::from_secs(2);
18	
19	/// Threads that take stamps at once: a Chakra program reads 1,855 files, 4 ms one at a time on macOS, 1.5 ms on four.
20	const STAMP_THREADS: usize = 4;
21	
22	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
23	pub(crate) enum Stamp {
24	    Missing,
25	    Present {
26	        modified: SystemTime,
27	        len: u64,
28	    },
29	    /// Modified too close to the read, or unreadable: the snapshot may hold either version, so it reads it again.
30	    Unsure,
31	}
32	
33	fn stamp(path: &Utf8Path) -> Stamp {
34	    match std::fs::metadata(path) {
35	        Ok(meta) => match meta.modified() {
36	            Ok(modified) => Stamp::Present { modified, len: meta.len() },
37	            Err(_) => Stamp::Unsure,
38	        },
39	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Stamp::Missing,
40	        Err(_) => Stamp::Unsure,
41	    }
42	}
43	
44	/// `stamp` of every path, on [`STAMP_THREADS`] threads.
45	fn stamp_all<T: Send>(paths: Vec<Utf8PathBuf>, stamp: impl Fn(&Utf8Path) -> T + Sync) -> Vec<(Utf8PathBuf, T)> {
46	    let chunk = paths.len().div_ceil(STAMP_THREADS).max(1);
47	    std::thread::scope(|scope| {
48	        let stamp = &stamp;
49	        let workers: Vec<_> = paths
50	            .chunks(chunk)
51	            .map(|part| scope.spawn(move || part.iter().map(|path| (path.clone(), stamp(path))).collect::<Vec<_>>()))
52	            .collect();
53	        workers
54	            .into_iter()
55	            .flat_map(|worker| worker.join().unwrap_or_else(|panic| std::panic::resume_unwind(panic)))
56	            .collect()
57	    })
58	}
59	
60	/// The stamps of the files a snapshot read, for a snapshot that started reading them at `read_from`. A path that is not
61	/// on the disk (a checker's built-in file) has no stamp.
62	pub(crate) fn record(files: Vec<Utf8PathBuf>, read_from: SystemTime) -> FxHashMap<Utf8PathBuf, Stamp> {
63	    let files = files.into_iter().filter(|file| file.is_absolute()).collect();
64	    stamp_all(files, |path| match stamp(path) {
65	        Stamp::Present { modified, .. } if modified + MTIME_GRANULARITY >= read_from => Stamp::Unsure,
66	        // Deleted after the snapshot read it, or never there: either way the checker is told it is gone.
67	        Stamp::Missing => Stamp::Unsure,
68	        stamp => stamp,
69	    })
70	    .into_iter()
71	    .collect()
72	}
73	
74	/// How the files a snapshot read differ from the disk now.
75	#[derive(Debug, Default, PartialEq, Eq)]
76	pub(crate) struct Drift {
77	    /// Changed since the snapshot read them, and the checker was told: it reads them again.
78	    pub(crate) told: Vec<Utf8PathBuf>,
79	    /// Unsure when the snapshot read them: read again, whatever their stamp says now.
80	    pub(crate) unsure: Vec<Utf8PathBuf>,
81	    /// Changed since the snapshot read them, and nobody told the checker: the snapshot cannot be trusted.
82	    pub(crate) untold: Vec<Utf8PathBuf>,
83	}
84	
85	/// The files of `stamps` whose stamp changed, split by whether `told` names them, and the unsure ones; each list sorted.
86	pub(crate) fn drift(stamps: &FxHashMap<Utf8PathBuf, Stamp>, told: &FxHashSet<Utf8PathBuf>) -> Drift {
87	    let mut drift = Drift::default();
88	    let (unsure, settled): (Vec<_>, Vec<_>) = stamps.iter().partition(|(_, stamp)| **stamp == Stamp::Unsure);
89	    drift.unsure = unsure.into_iter().map(|(path, _)| path.clone()).collect();
90	    let settled = settled.into_iter().map(|(path, _)| path.clone()).collect();
91	    for (path, now) in stamp_all(settled, stamp) {
92	        if stamps.get(&path) == Some(&now) {
93	            continue;
94	        }
95	        match told.contains(&path) {
96	            true => drift.told.push(path),
97	            false => drift.untold.push(path),
98	        }
99	    }
100	    for list in [&mut drift.told, &mut drift.unsure, &mut drift.untold] {
101	        list.sort();
102	    }
103	    drift
104	}
