689	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
690	        let wanted = requests.len();
691	        let scoped: Vec<Value> = requests
692	            .into_iter()
693	            .map(|(method, mut params)| {
694	                if let Value::Object(map) = &mut params {
695	                    map.insert("snapshot".to_string(), json!(self.snapshot));
696	                    map.insert("project".to_string(), json!(self.project));
697	                }
698	                json!({ "method": method, "params": params })
699	            })
700	            .collect();
701	        let mut answers = Vec::with_capacity(wanted);
702	        let mut token: Option<String> = None;
703	        loop {
704	            let mut params = json!({ "requests": scoped });
705	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
706	                map.insert("continuationToken".to_string(), json!(token));
707	            }
708	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
709	            for response in page.responses {
710	                if let Some(error) = response.error {
711	                    return Err(CallError::Rejected(error));
712	                }
713	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
714	            }
715	            match page.continuation_token {
716	                Some(next) => token = Some(next),
717	                None => break,
718	            }
719	        }
720	        if answers.len() != wanted {
721	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
722	        }
723	        Ok(answers)
724	    }
