//! Scratch (never committed): startup memory of a warm-up. `warm_mem <src> <warm|cold> <Component>`.
use std::time::{Duration, Instant};

use caliper_docgen_core::pipeline::{CollapseInheritedProps, PipelineOptions, extract};
use caliper_docgen_core::types::semantic::SemanticProvider;
use caliper_docgen_semantic::{OnDemand, OnDemandConfig, targets_of};
use camino::Utf8PathBuf;

#[global_allocator]
static ALLOCATOR: mimalloc::MiMalloc = mimalloc::MiMalloc;

fn arena_mib() -> u64 {
    let resident = tsrs_core::memsplit::resident(tsrs_core::reserve::base().addr(), tsrs_core::reserve::RESERVE);
    u64::try_from(resident >> 20).unwrap_or(u64::MAX)
}

fn rss_mib() -> u64 {
    let out = std::process::Command::new("ps").args(["-o", "rss=", "-p", &std::process::id().to_string()]).output().unwrap();
    String::from_utf8_lossy(&out.stdout).trim().parse::<u64>().unwrap_or(0) / 1024
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = Utf8PathBuf::from_path_buf(std::fs::canonicalize(&args[1]).unwrap()).unwrap();
    let warm = args[2] == "warm";
    let output = extract(&PipelineOptions {
        src_dirs: vec![src.clone()],
        load_dependencies: true,
        collapse_inherited_props: CollapseInheritedProps::None,
        ..PipelineOptions::default()
    });
    let target = targets_of(&output).into_iter().find(|t| t.display_name == args[3]).unwrap();
    let mut config = OnDemandConfig::new(src.clone());
    config.tsconfig = src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file());
    let checker = OnDemand::new(config);
    let (rss0, arena0) = (rss_mib(), arena_mib());
    let began = Instant::now();
    if warm {
        checker.warm_up();
    }
    drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
    let start_ms = began.elapsed().as_millis();
    let (rss1, arena1) = (rss_mib(), arena_mib());
    let began = Instant::now();
    let answer = checker.request(vec![target]).recv_timeout(Duration::from_secs(120)).unwrap();
    let first_ms = began.elapsed().as_millis();
    let (rss2, arena2) = (rss_mib(), arena_mib());
    println!(
        "{{\"warm\":{warm},\"components\":{},\"startMs\":{start_ms},\"firstMs\":{first_ms},\"rssBefore\":{rss0},\"arenaBefore\":{arena0},\"rssAfterWarm\":{rss1},\"arenaAfterWarm\":{arena1},\"rssAfterFirst\":{rss2},\"arenaAfterFirst\":{arena2}}}",
        answer.components.len()
    );
}

