379	/// The checker threads: one session, each thread answering the requests of its queue (its lane) in turn. The first
380	/// thread creates the session and starts the others.
381	fn serve<S: Served + Send + Sync + 'static>(
382	    open: impl FnOnce() -> S,
383	    queues: Vec<mpsc::Receiver<Job>>,
384	    ended: Arc<AtomicBool>,
385	    closing: mpsc::Sender<()>,
386	) {
387	    let session = Arc::new(open());
388	    let left = Arc::new(AtomicUsize::new(queues.len()));
389	    let mut queues = queues.into_iter();
390	    let Some(own) = queues.next() else {
391	        catch_unwind(AssertUnwindSafe(|| session.close())).ok();
392	        return;
393	    };
394	    for (index, queue) in queues.enumerate() {
395	        let lane =
396	            Lane { session: session.clone(), ended: ended.clone(), left: left.clone(), _closing: closing.clone() };
397	        let spawned = std::thread::Builder::new()
398	            .name(format!("caliper-checker-{}", index + 1))
399	            .stack_size(CHECKER_STACK_BYTES)
400	            .spawn(move || lane.answer(&queue));
401	        // Its queue is dropped with the closure, so its lane's requests fail as from a stopped checker.
402	        if spawned.is_err() {
403	            left.fetch_sub(1, Ordering::AcqRel);
404	        }
405	    }
406	    Lane { session, ended, left, _closing: closing }.answer(&own);
407	}
408	
409	/// What one checker thread shares with the others.
410	struct Lane<S> {
411	    session: Arc<S>,
412	    /// Set, before its reply, by the thread whose request a panic unwound through: no thread answers after it.
413	    ended: Arc<AtomicBool>,
414	    /// The threads that have not left; the last to leave closes the session.
415	    left: Arc<AtomicUsize>,
416	    /// Dropped as the thread leaves: [`Backend::closed`] disconnects once every thread has.
417	    _closing: mpsc::Sender<()>,
418	}
419	
